  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'application-deadline', 'DEADLINE', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"An applicant must apply to the Public Service Development Agency for a residence permit 40 calendar days before their lawful stay in Georgia expires.","ka":"ბინადრობის ნებართვისთვის განცხადება სახელმწიფო სერვისების განვითარების სააგენტოში უნდა შეიტანოთ საქართველოში კანონიერი ყოფნის ამოწურვამდე 40 კალენდარული დღით ადრე.","ru":"Заявление на вид на жительство подаётся в Агентство развития государственных сервисов за 40 календарных дней до окончания законного пребывания в Грузии.","tr":"Oturma izni başvurusu, Gürcistan''daki yasal kalış süresi dolmadan 40 takvim günü önce Kamu Hizmetleri Geliştirme Ajansı''na yapılmalıdır.","ar":"يجب تقديم طلب تصريح الإقامة إلى وكالة تطوير الخدمات العامة قبل انتهاء الإقامة المشروعة في جورجيا بأربعين يوماً تقويمياً.","he":"יש להגיש בקשה לרישיון ישיבה לסוכנות פיתוח השירותים הציבוריים 40 ימים קלנדריים לפני תום השהות החוקית בגאורגיה."}'::jsonb, '{"amount":40,"unit":"DAYS_BEFORE_STAY_EXPIRY"}'::jsonb, null,
       false
from public.expat_topics where slug = 'residence-permits'
on conflict (topic_id, fact_key) do update set
  fact_class = excluded.fact_class,
  register = excluded.register,
  availability = excluded.availability,
  statement = excluded.statement,
  value = excluded.value,
  applies_to_nationalities = excluded.applies_to_nationalities,
  needs_review = excluded.needs_review,
  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'residence-permits'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Public Service Development Agency of Georgia' and url is not distinct from 'https://sda.gov.ge/en/products/migration-residence-permits/'
  order by created_at limit 1) c
where f.fact_key = 'application-deadline'
on conflict do nothing;
