select id, 'standard-fee', 'FEE', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"A standard residence permit decision on the 30th calendar day costs GEL 300; GEL 450 on the 20th day and GEL 600 on the 10th.","ka":"ბინადრობის ნებართვის სტანდარტული გადაწყვეტილება მე-30 კალენდარულ დღეს 300 ლარი ღირს, მე-20 დღეს 450 ლარი, მე-10-ზე 600 ლარი.","ru":"Стандартное решение по виду на жительство на 30-й календарный день стоит 300 лари, на 20-й — 450 лари, на 10-й — 600 лари.","tr":"Otuzuncu takvim gününde verilen standart oturma izni kararı 300 lari, yirminci günde 450 lari, onuncu günde 600 laridir.","ar":"قرار تصريح الإقامة القياسي في اليوم الثلاثين يكلف 300 لاري، وفي اليوم العشرين 450 لاري، وفي العاشر 600 لاري.","he":"החלטה רגילה על רישיון ישיבה ביום הקלנדרי ה־30 עולה 300 לארי, ביום ה־20 עולה 450 לארי וביום ה־10 עולה 600 לארי."}'::jsonb, '{"amount":300,"currency":"GEL","unit":"ONE_OFF","decisionDays":30}'::jsonb, null,
       false
from public.expat_topics where slug = 'residence-permits'
