  content = excluded.content,
  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'tbilisi-transport-monthly', 'PRICE', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"A month of unlimited travel on Tbilisi public transport costs GEL 40. A single 90-minute journey costs GEL 1.","ka":"თბილისის საზოგადოებრივ ტრანსპორტში თვიური შეუზღუდავი მგზავრობა 40 ლარი ღირს. ერთი 90-წუთიანი მგზავრობა 1 ლარია.","ru":"Месяц безлимитных поездок в общественном транспорте Тбилиси стоит 40 лари. Одна поездка на 90 минут — 1 лари.","tr":"Tiflis toplu taşımasında bir aylık sınırsız seyahat 40 lari tutar. Tek bir 90 dakikalık yolculuk 1 laridir.","ar":"شهر من التنقل غير المحدود في نقل تبليسي العام يكلف 40 لاري. والرحلة الواحدة لمدة 90 دقيقة تكلف 1 لاري.","he":"חודש נסיעות ללא הגבלה בתחבורה הציבורית בטביליסי עולה 40 לארי. נסיעה בודדת של 90 דקות עולה 1 לארי."}'::jsonb, '{"amount":40,"currency":"GEL","unit":"PER_MONTH"}'::jsonb, null,
       false
from public.expat_topics where slug = 'cost-of-living'
on conflict (topic_id, fact_key) do update set
  fact_class = excluded.fact_class,
  register = excluded.register,
  availability = excluded.availability,
  statement = excluded.statement,
  value = excluded.value,
  applies_to_nationalities = excluded.applies_to_nationalities,
  needs_review = excluded.needs_review,
  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'cost-of-living'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Tbilisi Transport Company' and url is not distinct from 'https://ttc.com.ge/en/tariff/10'
  order by created_at limit 1) c
where f.fact_key = 'tbilisi-transport-monthly'
on conflict do nothing;
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
