select id, 'tbilisi-electricity-tariff', 'PRICE', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"Tbilisi household electricity, effective April 2026: 20.041 tetri per kWh up to 101 kWh a month, 24.053 from 101 to 301, and 28.537 above that. Reported from the regulator''s decision rather than read on the regulator''s own site.","ka":"თბილისის საყოფაცხოვრებო ელექტროენერგია, 2026 წლის აპრილიდან: 20.041 თეთრი კვტსთ-ზე თვეში 101 კვტსთ-მდე, 24.053 — 101-დან 301-მდე, 28.537 — ზემოთ. მოყვანილია მარეგულირებლის გადაწყვეტილების შესახებ ცნობიდან და არა თავად მარეგულირებლის საიტიდან.","ru":"Электроэнергия для домохозяйств Тбилиси, с апреля 2026 года: 20,041 тетри за кВт·ч до 101 кВт·ч в месяц, 24,053 — от 101 до 301, 28,537 — свыше. Приводится по сообщению о решении регулятора, а не с сайта самого регулятора.","tr":"Tiflis konut elektriği, Nisan 2026''dan itibaren: ayda 101 kWh''ye kadar kWh başına 20,041 tetri, 101–301 arası 24,053, üzeri 28,537. Düzenleyicinin kendi sitesinden değil, kararına ilişkin habere dayanılarak aktarılmıştır.","ar":"كهرباء المنازل في تبليسي، اعتباراً من أبريل 2026: 20.041 تتري لكل كيلوواط ساعة حتى 101 كيلوواط ساعة شهرياً، و24.053 من 101 إلى 301، و28.537 لما فوق. منقول عن خبر بقرار الجهة المنظِّمة لا عن موقعها.","he":"חשמל ביתי בטביליסי, החל מאפריל 2026: 20.041 טטרי לקוט\"ש עד 101 קוט\"ש בחודש, 24.053 בין 101 ל־301, ו־28.537 מעבר לכך. מדווח מתוך ההחלטה של הרגולטור ולא נקרא באתר הרגולטור עצמו."}'::jsonb, '{"bands":[[0,101,0.20041],[101,301,0.24053],[301,null,0.28537]],"currency":"GEL","unit":"PER_ITEM"}'::jsonb, null,
       false
from public.expat_topics where slug = 'cost-of-living'
on conflict (topic_id, fact_key) do update set
