-- buying-property
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('buying-property', 'GE', 'PROPERTY', 'BUY', '{"en":{"title":"Buying property in Georgia as a foreigner","summary":"Foreigners buy apartments here routinely. What separates a good purchase from a bad one is almost never the price — it is what you knew about the building, the seller and the title before you signed.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"Residential property is registered at the National Agency of Public Registry, and a transfer is completed there. The paperwork itself is fast by international standards. The work worth doing is all before that: confirming who owns it, what is registered against it, whether the building is what it appears to be, and whether the price matches the market."},{"kind":"PRACTICAL","heading":"What to establish before you commit","body":"Ownership and any encumbrance on the title. The developer''s record if it is a new build. The observed price per square metre for that location, so you can tell whether the asking price is ordinary. The contract terms, particularly on payment schedule and handover. Homatch does the first three as separate products and they are linked from this page."},{"kind":"NOTES","heading":"A caution about land","body":"Apartments and buildings are one thing; agricultural land is a separate question with its own history of restrictions on foreign ownership. If your interest is land rather than a flat, take advice specific to the plot and the current rule, and do not assume the apartment answer applies."}]},"ka":{"title":"უძრავი ქონების ყიდვა საქართველოში უცხოელისთვის","summary":"უცხოელები აქ ბინებს რეგულარულად ყიდულობენ. კარგ და ცუდ გარიგებას შორის სხვაობას თითქმის არასდროს ფასი ქმნის. სხვაობას ქმნის ის, რაც ხელმოწერამდე იცოდით შენობაზე, გამყიდველსა და საკუთრების უფლებაზე.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"საცხოვრებელი ქონება საჯარო რეესტრის ეროვნულ სააგენტოში რეგისტრირდება და გადაფორმებაც იქ სრულდება. თავად ქაღალდები საერთაშორისო სტანდარტით სწრაფად კეთდება. ნამდვილი სამუშაო ამის წინაა: ვის ეკუთვნის, რა არის რეგისტრირებული ქონებაზე, არის თუ არა შენობა ის, რაც ჩანს, და შეესაბამება თუ არა ფასი ბაზარს."},{"kind":"PRACTICAL","heading":"რა უნდა დაადასტუროთ ვალდებულების აღებამდე","body":"საკუთრება და ნებისმიერი ყადაღა თუ დატვირთვა. დეველოპერის ისტორია, თუ ახალი მშენებლობაა. ამ ლოკაციის დაკვირვებული ფასი კვადრატულ მეტრზე, რომ გაიგოთ, ჩვეულებრივია თუ არა მოთხოვნილი თანხა. ხელშეკრულების პირობები, განსაკუთრებით გადახდის გრაფიკი და ჩაბარება. პირველ სამს Homatch ცალკე პროდუქტებად აკეთებს და ისინი აქედან მისაწვდომია."},{"kind":"NOTES","heading":"გაფრთხილება მიწაზე","body":"ბინები და შენობები ერთია, სასოფლო-სამეურნეო მიწა კი ცალკე საკითხია, უცხოელის მფლობელობაზე შეზღუდვების საკუთარი ისტორიით. თუ მიწა გაინტერესებთ და არა ბინა, აიღეთ კონკრეტულ ნაკვეთსა და მოქმედ წესზე მორგებული რჩევა და ნუ ჩათვლით, რომ ბინის პასუხი აქაც მოქმედებს."}]},"ru":{"title":"Покупка недвижимости в Грузии иностранцем","summary":"Иностранцы покупают здесь квартиры регулярно. Хорошую сделку от плохой почти никогда не отличает цена — её отличает то, что вы знали о здании, продавце и праве собственности до подписания.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Жилая недвижимость регистрируется в Национальном агентстве публичного реестра, там же оформляется переход права. Сами бумаги по международным меркам делаются быстро. Вся работа, которую стоит делать, — до этого: кто владеет, что зарегистрировано в отношении объекта, является ли здание тем, чем кажется, и соответствует ли цена рынку."},{"kind":"PRACTICAL","heading":"Что установить до обязательств","body":"Собственность и любые обременения. Историю застройщика, если это новостройка. Наблюдаемую цену за квадратный метр в этой локации, чтобы понять, обычна ли запрошенная сумма. Условия договора, особенно график платежей и передачу объекта. Первые три Homatch делает отдельными продуктами, и они доступны с этой страницы."},{"kind":"NOTES","heading":"Предостережение о земле","body":"Квартиры и здания — одно, сельскохозяйственная земля — отдельный вопрос со своей историей ограничений для иностранцев. Если вас интересует земля, а не квартира, получите консультацию по конкретному участку и действующему правилу и не считайте, что ответ про квартиру подходит."}]},"tr":{"title":"Yabancı olarak Gürcistan''da gayrimenkul almak","summary":"Yabancılar burada rutin olarak daire alıyor. İyi bir alımı kötüsünden ayıran şey neredeyse hiçbir zaman fiyat değildir; imzadan önce bina, satıcı ve tapu hakkında ne bildiğinizdir.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısa cevap","body":"Konut, Ulusal Kamu Sicil Ajansı''nda kayıtlıdır ve devir de orada tamamlanır. Evrak işi uluslararası ölçülere göre hızlıdır. Yapılmaya değer iş bunun öncesindedir: kime ait olduğu, üzerinde ne kayıtlı olduğu, binanın göründüğü şey olup olmadığı ve fiyatın piyasaya uyup uymadığı."},{"kind":"PRACTICAL","heading":"Bağlanmadan önce netleştirilecekler","body":"Mülkiyet ve tapu üzerindeki her türlü takyidat. Yeni yapıysa müteahhidin geçmişi. O konum için gözlemlenmiş metrekare fiyatı, böylece istenen bedelin olağan olup olmadığını anlarsınız. Sözleşme şartları, özellikle ödeme planı ve teslim. İlk üçünü Homatch ayrı ürünler olarak yapıyor ve bu sayfadan bağlantılıdır."},{"kind":"NOTES","heading":"Arazi konusunda bir uyarı","body":"Daire ve bina başka, tarım arazisi ise yabancı mülkiyetine dair kendi kısıtlama geçmişi olan ayrı bir konudur. İlginiz daire değil arazi ise, ilgili parsele ve yürürlükteki kurala özgü danışmanlık alın; daire için geçerli cevabın burada da geçtiğini varsaymayın."}]},"ar":{"title":"شراء عقار في جورجيا بصفتك أجنبياً","summary":"يشتري الأجانب الشقق هنا بشكل اعتيادي. وما يفرّق بين صفقة جيدة وأخرى سيئة لا يكاد يكون السعر، بل ما عرفته عن المبنى والبائع وسند الملكية قبل أن توقّع.","sections":[{"kind":"SHORT_ANSWER","heading":"الجواب باختصار","body":"تُسجَّل العقارات السكنية لدى الوكالة الوطنية للسجل العام، وهناك يُستكمل نقل الملكية. والمعاملة الورقية نفسها سريعة بالمقاييس الدولية. أما العمل الذي يستحق الجهد فكله قبل ذلك: من المالك، وما المسجَّل على العقار، وهل المبنى كما يبدو، وهل السعر يوافق السوق."},{"kind":"PRACTICAL","heading":"ما ينبغي التثبت منه قبل الالتزام","body":"الملكية وأي رهن أو قيد على السند. سجل المطوِّر إن كان البناء جديداً. السعر المرصود للمتر المربع في ذلك الموقع، لتعرف إن كان المطلوب اعتيادياً. وشروط العقد، وبخاصة جدول الدفع والتسليم. الثلاثة الأولى تقدّمها Homatch كمنتجات مستقلة، وهي موصولة من هذه الصفحة."},{"kind":"NOTES","heading":"تنبيه بشأن الأراضي","body":"الشقق والمباني شيء، والأراضي الزراعية مسألة منفصلة لها تاريخها الخاص من القيود على تملّك الأجانب. فإن كان اهتمامك أرضاً لا شقة، فاطلب مشورة خاصة بتلك القطعة وبالقاعدة النافذة، ولا تفترض أن جواب الشقة ينطبق."}]},"he":{"title":"רכישת נכס בגאורגיה כזר","summary":"זרים קונים כאן דירות באופן שגרתי. מה שמבדיל עסקה טובה מרעה כמעט אף פעם אינו המחיר — אלא מה ידעתם על הבניין, על המוכר ועל הבעלות לפני שחתמתם.","sections":[{"kind":"SHORT_ANSWER","heading":"התשובה הקצרה","body":"נכסי מגורים רשומים בסוכנות הלאומית לרישום המקרקעין, ושם גם מושלמת ההעברה. הניירת עצמה מהירה במונחים בינלאומיים. כל העבודה שכדאי לעשות היא לפני כן: מי הבעלים, מה רשום על הנכס, האם הבניין הוא מה שהוא נראה, והאם המחיר תואם את השוק."},{"kind":"PRACTICAL","heading":"מה לברר לפני שמתחייבים","body":"בעלות וכל שעבוד או עיקול. עברו של היזם אם מדובר בבנייה חדשה. המחיר שנצפה למטר רבוע באותו מיקום, כדי לדעת אם המחיר המבוקש רגיל. תנאי החוזה, ובעיקר לוח התשלומים והמסירה. את שלושת הראשונים Homatch עושה כמוצרים נפרדים, והם מקושרים מהעמוד הזה."},{"kind":"NOTES","heading":"אזהרה בעניין קרקע","body":"דירות ובניינים הם דבר אחד; קרקע חקלאית היא שאלה נפרדת עם היסטוריה משלה של הגבלות על בעלות זרה. אם מה שמעניין אתכם הוא קרקע ולא דירה, קבלו ייעוץ ספציפי לחלקה ולכלל התקף, ואל תניחו שהתשובה לגבי דירה חלה גם כאן."}]}}'::jsonb,
        'PROCESS', 'PRACTICAL_CONTEXT', 10,
        true, false, null,
        now(), now() + interval '90 days')
on conflict (slug) do update set
  domain = excluded.domain,
  pathway = excluded.pathway,
  content = excluded.content,
  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();

-- Observed prices. Supersede rather than overwrite, so a change is visible.
update public.expat_cost_observations set status = 'SUPERSEDED'
where status = 'CURRENT' and country = 'GE' and city = 'Tbilisi'
  and coalesce(district,'') = '' and category = 'TRANSPORT' and unit = 'PER_MONTH'
  and (low, high, observed_at) is distinct from (40::numeric, 40::numeric, '2026-09-20T00:00:00Z'::timestamptz);
insert into public.expat_cost_observations
  (country, city, district, category, low, high, currency, unit,
   sample_size, source_count, observed_at, citation_id, status, notes)
select 'GE', 'Tbilisi', null, 'TRANSPORT', 40, 40,
       'GEL', 'PER_MONTH', 1, 1,
       '2026-09-20T00:00:00Z'::timestamptz, c.id, 'CURRENT', 'The operator''s published price for a one-month unlimited travel pass. Somebody paying per journey at GEL 1 for 90 minutes may spend less; this figure is the published pass, not a measured average of what people spend.'
from (select id from public.expat_citations
      where publisher = 'Tbilisi Transport Company' and url is not distinct from 'https://ttc.com.ge/en/tariff/10'
      order by created_at limit 1) c
where not exists (
  select 1 from public.expat_cost_observations e
  where e.status = 'CURRENT' and e.country = 'GE' and e.city = 'Tbilisi'
    and coalesce(e.district,'') = ''
    and e.category = 'TRANSPORT' and e.unit = 'PER_MONTH');
update public.expat_cost_observations set status = 'SUPERSEDED'
where status = 'CURRENT' and country = 'GE' and city = 'Tbilisi'
  and coalesce(district,'') = '' and category = 'INTERNET' and unit = 'PER_MONTH'
  and (low, high, observed_at) is distinct from (33::numeric, 80::numeric, '2026-09-20T00:00:00Z'::timestamptz);
insert into public.expat_cost_observations
  (country, city, district, category, low, high, currency, unit,
   sample_size, source_count, observed_at, citation_id, status, notes)
select 'GE', 'Tbilisi', null, 'INTERNET', 33, 80,
       'GEL', 'PER_MONTH', 3, 1,
       '2026-09-20T00:00:00Z'::timestamptz, c.id, 'CURRENT', 'Magticom''s published home fibre packages: 70 Mbps at GEL 33 promotional and GEL 40 standard, 80 Mbps at GEL 50, 100 Mbps at GEL 80. One operator''s list price, not a market survey.'
from (select id from public.expat_citations
      where publisher = 'Magticom' and url is not distinct from 'https://www.magticom.ge/en/internet/internet-tariffs/internet-packages'
      order by created_at limit 1) c
where not exists (
  select 1 from public.expat_cost_observations e
  where e.status = 'CURRENT' and e.country = 'GE' and e.city = 'Tbilisi'
    and coalesce(e.district,'') = ''
    and e.category = 'INTERNET' and e.unit = 'PER_MONTH');

commit;
